gt:"V + 得 + оценка · 比 (2) · 还是", gru:"Оценка действия через 得 (跑得很快); сравнение действий с 比; выбор «или» 还是", gen:"Rating an action with 得 (跑得很快); comparing actions with 比; choosing “or” with 还是",
gram:()=>`
${LEAD(TZ(`Чтобы сказать, <b>как</b> делается действие (быстро, хорошо, рано), после глагола ставят ${Z("得")} и оценку: ${Z("他跑"+ZK("得")+"很快。")}`, `To say <b>how</b> something is done (fast, well, early), put ${Z("得")} after the verb and then the rating: ${Z("他跑"+ZK("得")+"很快。")}`))}
${SEC(TZ("Глагол + 得 + оценка","Verb + 得 + rating"))}
${PAIRS([TZ("Кто","Who"), TZ("Глагол","Verb"), "得", TZ("Как","How")],[[Z("他"), Z("说"), Z(ZK("得")), Z("很好。")],[Z("我"), Z("起"), Z(ZK("得")), Z("很早。")],[Z("我"), Z("睡"), Z(ZK("得")), Z("也早。")]])}
${SEC(TZ("Если есть дополнение — повтори глагол","With an object — repeat the verb"))}
${PAIRS([TZ("Глагол + дополнение","Verb + object"), TZ("Глагол ещё раз + 得","Verb again + 得"), TZ("Как","How")],[[Z("他（说）汉语"), Z("说"+ZK("得")), Z("很好。")],[Z("你做饭"), Z("做"+ZK("得")), Z("怎么样？")],[Z("姐姐（唱）歌"), Z("唱"+ZK("得")), Z("不错。")]])}
${KCAP(TZ(`Первый глагол можно опустить: ${Z("他汉语说得很好。")}`, `The first verb can be dropped: ${Z("他汉语说得很好。")}`))}
${SEC(TZ("Отрицание и вопрос","Negative and question"))}
${CHOOSE([{lab:TZ("Отрицание: 不 после 得","Negative: 不 after 得"), key:"说得不好", acc:true, ex:[Z("他说汉语说得不好。"), Z("我起得不早。")]},{lab:TZ("Вопрос: прил. + 不 + прил.","Question: adj + 不 + adj"), key:"说得好不好？", ex:[Z("你住得远不远？"), Z("姐姐起得早不早？")]}])}
${ASIDE(TZ(`${Z("不")} ставится после ${Z("得")}, а не перед глаголом: ${KX(Z("他不说得好。"))}`, `${Z("不")} goes after ${Z("得")}, not before the verb: ${KX(Z("他不说得好。"))}`))}
${SEC(TZ("比 со словом 得","比 with 得"))}
${PAIRS([TZ("Вариант 1","Option 1"), TZ("Вариант 2","Option 2")],[[Z("他"+ZK("比")+"我学得好。"), Z("他学得"+ZK("比")+"我好。")],[Z("姐姐"+ZK("比")+"我跑得快。"), Z("姐姐跑得"+ZK("比")+"我快。")],[Z("我妻子"+ZK("比")+"我做得好。"), Z("我妻子做得"+ZK("比")+"我好。")]])}
${SEC(TZ("还是: «или» в вопросе","还是: “or” in a question"))}
${ZEX([["你喜欢吃米饭"+ZK("还是")+"吃面条？","Nǐ xǐhuan chī mǐfàn háishi chī miàntiáo?","Ты любишь рис или лапшу?","Do you like rice or noodles?"],["你想今天去"+ZK("还是")+"明天去？","Nǐ xiǎng jīntiān qù háishi míngtiān qù?","Ты хочешь пойти сегодня или завтра?","Do you want to go today or tomorrow?"]])}
${SEC(TZ("Проверь себя","Check yourself"))}
${QUIZ([[TZ("«Он бегает очень быстро»","“He runs very fast”"), Z("他跑得很快。")],[TZ("«Я пишу иероглифы некрасиво»","“My characters aren't pretty”"), Z("我写汉字写得不好看。")],[TZ("Спроси: «Ты далеко живёшь?» (через 得)","Ask: “Do you live far?” (with 得)"), Z("你住得远不远？")]])}`,
